function Find-Central{$n=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('MDBf7KSR7JWZ7JeQ7J207KCE7Yq4'));$m=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('64K0IOuTnOudvOydtOu4jA=='));foreach($d in @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)){if(-not$d.Root){continue};foreach($c in @((Join-Path $d.Root $n),(Join-Path $d.Root ('My Drive\'+$n)),(Join-Path $d.Root ($m+'\'+$n)),(Join-Path $d.Root ('Google Drive\'+$n)))){if(Test-Path -LiteralPath $c -PathType Container){return $c}}};return ''}
function GitBlob([byte[]]$b){$h=[Text.Encoding]::ASCII.GetBytes(('blob '+$b.Length+[char]0));$a=New-Object byte[]($h.Length+$b.Length);[Buffer]::BlockCopy($h,0,$a,0,$h.Length);[Buffer]::BlockCopy($b,0,$a,$h.Length,$b.Length);$s=[Security.Cryptography.SHA1]::Create();try{return (($s.ComputeHash($a)|ForEach-Object{$_.ToString('x2')})-join '')}finally{$s.Dispose()}}
function Refresh-Pinned([string]$RepoPath){$pin=$Pins[$RepoPath];if(-not$pin){return ''};$dest=[string]$pin.dest;$expected=([string]$pin.sha).ToLowerInvariant();try{$u='https://raw.githubusercontent.com/'+$Repo+'/'+[string]$pin.commit+'/'+$RepoPath;$wc=New-Object Net.WebClient;try{$wc.Headers['User-Agent']='HomeDesign-Supervisor-V25';$b=$wc.DownloadData($u)}finally{$wc.Dispose()};$actual=(GitBlob $b).ToLowerInvariant();if($actual-ne$expected){throw 'PIN_SHA_MISMATCH'};$tmp=$dest+'.v25';[IO.File]::WriteAllBytes($tmp,$b);Move-Item $tmp $dest -Force;return $actual}catch{};try{if(Test-Path $dest){$actual=(GitBlob ([IO.File]::ReadAllBytes($dest))).ToLowerInvariant();if($actual-eq$expected){return $actual}}}catch{};return ''}
function Run-Json([string]$Path,[string[]]$ScriptArgs=@()){$o=[ordered]@{exit=9;obj=$null;raw='';error=''};try{$o.raw=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $Path @ScriptArgs 2>&1|Out-String;$o.exit=$LASTEXITCODE;try{$o.obj=$o.raw|ConvertFrom-Json}catch{$lines=@($o.raw-split"`r?`n"|Where-Object{$_.Trim().StartsWith('{')});if($lines.Count){$o.obj=$lines[-1]|ConvertFrom-Json}else{throw}}}catch{$o.error=$_.Exception.Message};return [pscustomobject]$o}
function Test-LocalHost{try{$h=Invoke-RestMethod 'http://127.0.0.1:8765/health' -TimeoutSec 3;return [bool]$h.ok}catch{return $false}}
function Test-Cdp{try{$v=Invoke-RestMethod 'http://127.0.0.1:9224/json/version' -TimeoutSec 3;return [bool]$v.Browser}catch{return $false}}
function Test-Remote{try{$p=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{([string]$_.Name)-match'(?i)^node(?:\.exe)?$'-and[string]$_.CommandLine-match'(?i)desktop-commander'-and[string]$_.CommandLine-match'(?i)(?:^|\s)remote(?:\s|$)'});if($p.Count-eq0){return $false};$ids=@($p|ForEach-Object{[int]$_.ProcessId});return (@(Get-NetTCPConnection -State Established -ErrorAction SilentlyContinue|Where-Object{$ids-contains$_.OwningProcess}).Count-gt0)}catch{return $false}}
function Read-PowerReceipt{try{if(Test-Path $PowerGuardReceipt){return Get-Content $PowerGuardReceipt -Raw -Encoding UTF8|ConvertFrom-Json}}catch{};return $null}
function Get-PowerGuardProcs{return @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{[string]$_.CommandLine-match'(?i)CentralAgentPowerContinuityGuard\.ps1'})}
function Ensure-PowerGuard{$o=[ordered]@{sha='';ok=$false;processCount=0;receiptVersion='';mode='';remoteLeaseActive=$false;systemRequiredHeld=$false;displayRequiredHeld=$false;screenOffAllowed=$true;trueSleepAllowed=$true;restarted=$false;error=''};try{$o.sha=Refresh-Pinned 'local-agent/bootstrap/CentralAgentPowerContinuityGuard.ps1';if(-not$o.sha){throw 'POWER_GUARD_REFRESH_FAILED'};$rr=Read-PowerReceipt;$procs=@(Get-PowerGuardProcs);$restart=($procs.Count-eq0-or-not$rr-or[string]$rr.version-ne$RequiredPowerGuardVersion);if($restart){foreach($p in $procs){try{Stop-Process -Id ([int]$p.ProcessId) -Force -ErrorAction SilentlyContinue}catch{}};Start-Sleep -Milliseconds 500;Start-Process powershell.exe -ArgumentList @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',$PowerGuardScript) -WindowStyle Hidden|Out-Null;Start-Sleep -Seconds 3;$o.restarted=$true};$procs=@(Get-PowerGuardProcs);$rr=Read-PowerReceipt;$o.processCount=$procs.Count;if($rr){$o.receiptVersion=[string]$rr.version;$o.mode=[string]$rr.mode;$o.remoteLeaseActive=[bool]$rr.remoteLeaseActive;$o.systemRequiredHeld=[bool]$rr.systemRequiredHeld;$o.displayRequiredHeld=[bool]$rr.displayRequiredHeld;$o.screenOffAllowed=[bool]$rr.screenOffAllowed;$o.trueSleepAllowed=[bool]$rr.trueSleepAllowed;$modeOk=[bool]($o.systemRequiredHeld-and-not$o.trueSleepAllowed-and(((-not$o.remoteLeaseActive)-and-not$o.displayRequiredHeld)-or($o.remoteLeaseActive-and$o.displayRequiredHeld-and-not$o.screenOffAllowed)));$o.ok=[bool]($procs.Count-eq1-and$o.receiptVersion-eq$RequiredPowerGuardVersion-and$modeOk)}}catch{$o.error=$_.Exception.Message};return [pscustomobject]$o}
function Get-CloudControl{
  $o=[ordered]@{valid=$false;requestId='';action='';reason='';alreadyApplied=$false;status='UNREAD';error=''}
  try{
    $u='https://api.github.com/repos/'+$Repo+'/contents/local-agent/control/remote-recovery.json?ref=main&cb='+[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
    $x=Invoke-RestMethod $u -Headers @{'User-Agent'='HomeDesign-Supervisor-V27';'Accept'='application/vnd.github+json'} -TimeoutSec 10
    $j=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(([string]$x.content-replace'\s','')))|ConvertFrom-Json
    $o.requestId=[string]$j.requestId;$o.action=[string]$j.action;$o.reason=[string]$j.reason
    if([string]$j.device-ne$env:COMPUTERNAME){$o.status='IGNORED_DEVICE_MISMATCH';return [pscustomobject]$o}
    if([string]$j.action-ne'FORCE_REMOTE_RESTART_ONCE'){$o.status='IGNORED_ACTION_NOT_ALLOWED';return [pscustomobject]$o}
    if([datetime]$j.expiresAt-lt(Get-Date).ToUniversalTime()){$o.status='IGNORED_EXPIRED';return [pscustomobject]$o}
    try{if(Test-Path $CloudControlReceipt){$a=Get-Content $CloudControlReceipt -Raw -Encoding UTF8|ConvertFrom-Json;if([string]$a.requestId-eq$o.requestId){$o.alreadyApplied=$true;$o.status='ALREADY_APPLIED';return [pscustomobject]$o}}}catch{}
    $o.valid=$true;$o.status='VALID_PENDING'
  }catch{$o.status='ERROR';$o.error=$_.Exception.Message}
  [pscustomobject]$o
}
