if(-not$rgOk){$issues.Add('REMOTE_GUARD_NOT_OK')};if(-not$waOk){$issues.Add('WINDOW_UIA_NOT_OK_OR_EMPTY')};if(-not$wgOk){$issues.Add('WORKLOAD_ADMISSION_NOT_OK')};if(-not$clOk){$issues.Add('CLEANUP_V7_NOT_OK')};if(-not$igOk){$issues.Add('INACTIVE_R2_NOT_OK')}
